{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Compound 4 had a brain–blood ratio of only 0.07 in mice, directly indicating poor CNS penetration; its morpholine, fluorophenyl, and heteroaromatic motifs are shared with the query, so this measured phenotype transfers as a liability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Peposertib showed Kp,uu,brain of 5% and Kp,uu,spinal cord of 3% in mice after oral dosing, demonstrating severely restricted CNS distribution despite a morpholine/fluorophenyl/heteroaromatic scaffold similar to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "CZC25146, a morpholine-aniline aminopyrimidine analogue, had negligible brain penetration in mice, supporting the query's likely inadequate CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "The radiotracer M4K2163 showed low brain uptake (peak SUV 1.1) in rats, indicating that a related polar heteroaromatic basic amine does not achieve meaningful brain exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "The closest-scoring analogue was brain penetrant by PET (initial SUV 2.8), but it is much smaller and less polar than the query, so this positive result is only weakly transferable.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C08"],
      "claim": "PF-06455943 showed favorable brain uptake in rodents, but it is a smaller morpholine-containing heteroaromatic radioligand; this supports some potential for CNS access but is outweighed by larger, more polar failing analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted fail: the query's large, highly polar, fully ionized structure and multiple direct measurements on structurally related morpholine/fluorophenyl/heteroaromatic kinase inhibitors showing poor brain penetration outweigh the few positive brain-uptake results from smaller analogues.",
  "evidence_gaps": [
    "No direct Kp,uu,brain, CSF, or PET data for the exact query molecule.",
    "Morgan similarities are low (0.21–0.32), limiting quantitative transfer.",
    "Predicted pKa/logD/TPSA may have uncertainty; active uptake/efflux status of the query is unknown.",
    "Positive analogues are smaller and less polar, so their good brain penetration may not translate to the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

